const SOL_USDC = 'EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v';
const SPL_TOKEN_PROGRAMS = new Set([
  'TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA',
  'TokenzQdBNbLqP5VEhdkAS6EPFLC1PHnBqCXEpPxuEb'
]);
const BASE58_ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
const BASE58_MAP = new Map(Array.from(BASE58_ALPHABET).map((c, i) => [c, i]));
const PUBKEY_RE = /^[1-9A-HJ-NP-Za-km-z]{32,44}$/;
const SIG_RE = /^[1-9A-HJ-NP-Za-km-z]{32,128}$/;
const UINT_RE = /^\d+$/;

const SECRET = String($env.WEBHOOK_HMAC_SECRET || '').trim();
if (SECRET.length < 16) {
  throw new Error('WEBHOOK_HMAC_SECRET (>= 16 chars) must be configured');
}
const VAULT = String($env.SOLANA_RECEIVE_ADDRESS || '').trim();
if (!PUBKEY_RE.test(VAULT)) {
  throw new Error('SOLANA_RECEIVE_ADDRESS must be a valid non-empty Solana public key');
}
const ENV_EXPECTED_REF = String($env.EXPECTED_REFERENCE_KEY || '').trim();
const ALLOW_SIGNED_PAYLOAD_REF = String($env.ALLOW_SIGNED_PAYLOAD_REFERENCE || 'false').trim().toLowerCase() === 'true';
if (!ALLOW_SIGNED_PAYLOAD_REF) {
  if (!PUBKEY_RE.test(ENV_EXPECTED_REF)) {
    throw new Error('EXPECTED_REFERENCE_KEY must be a valid non-empty Solana reference public key');
  }
  if (ENV_EXPECTED_REF === VAULT || ENV_EXPECTED_REF === SOL_USDC) {
    throw new Error('EXPECTED_REFERENCE_KEY must be distinct from SOLANA_RECEIVE_ADDRESS and USDC mint');
  }
}
const EXPECTED_RAW = String($env.EXPECTED_AMOUNT_ATOMIC || '').trim();
if (!/^[1-9][0-9]*$/.test(EXPECTED_RAW)) {
  throw new Error('EXPECTED_AMOUNT_ATOMIC must be a positive integer string');
}
const EXPECTED_AMOUNT_ATOMIC = BigInt(EXPECTED_RAW);
const SOLANA_RPC_URL = String($env.SOLANA_RPC_URL || '').trim();
if (!/^https?:\/\//i.test(SOLANA_RPC_URL)) {
  throw new Error('SOLANA_RPC_URL must be configured');
}
const MAX_AGE_RAW = String($env.MAX_WEBHOOK_AGE_SECONDS || '300').trim();
if (!/^[1-9][0-9]*$/.test(MAX_AGE_RAW)) {
  throw new Error('MAX_WEBHOOK_AGE_SECONDS must be a positive integer');
}
const MAX_WEBHOOK_AGE_SECONDS = Number(MAX_AGE_RAW);

function decodeBase58(input) {
  if (typeof input !== 'string' || input.length === 0) throw new Error('Empty base58');
  const bytes = [];
  for (const ch of input) {
    const v = BASE58_MAP.get(ch);
    if (v === undefined) throw new Error('Invalid base58');
    let carry = v;
    for (let i = 0; i < bytes.length; i++) {
      carry += bytes[i] * 58;
      bytes[i] = carry & 0xff;
      carry >>= 8;
    }
    while (carry > 0) {
      bytes.push(carry & 0xff);
      carry >>= 8;
    }
  }
  for (let i = 0; i < input.length && input[i] === '1'; i++) bytes.push(0);
  return Uint8Array.from(bytes.reverse());
}

function readU64Le(bytes, offset) {
  let out = 0n;
  for (let i = 7; i >= 0; i--) out = (out << 8n) | BigInt(bytes[offset + i]);
  return out;
}

function parseAtomic(val, label) {
  if (typeof val !== 'string' || !UINT_RE.test(val)) {
    throw new Error(`Invalid ${label} atomic integer string`);
  }
  return BigInt(val);
}

async function sha256Hex(text) {
  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text)));
  return Array.from(digest, (b) => b.toString(16).padStart(2, '0')).join('');
}

function extractRawPayload(item) {
  const binData = item?.binary?.data?.data;
  if (typeof binData === 'string' && binData.length > 0) {
    return Buffer.from(binData, 'base64').toString('utf8');
  }
  if (binData instanceof Uint8Array && binData.length > 0) {
    return Buffer.from(binData).toString('utf8');
  }
  if (typeof item?.json?.rawBody === 'string' && item.json.rawBody.length > 0) {
    return item.json.rawBody;
  }
  if (item?.json?.body !== undefined) {
    return JSON.stringify(item.json.body);
  }
  return '';
}

function pushKeys(out, entries) {
  if (!Array.isArray(entries)) return;
  for (const e of entries) {
    if (typeof e === 'string' && e.length > 0) out.push(e);
    else if (e && typeof e === 'object' && typeof e.pubkey === 'string') out.push(e.pubkey);
  }
}

function resolveAccountRef(ref, keys) {
  if (typeof ref === 'number') return Number.isInteger(ref) && ref >= 0 && ref < keys.length ? keys[ref] : null;
  return typeof ref === 'string' && ref.length > 0 ? ref : null;
}

function decodeMatchedSplAmount(ix, keys, refKey, validDestKeys) {
  const progId = typeof ix?.programId === 'string' ? ix.programId : resolveAccountRef(ix?.programIdIndex, keys);
  if (!progId || !SPL_TOKEN_PROGRAMS.has(progId)) return 0n;
  if (!Array.isArray(ix.accounts) || typeof ix.data !== 'string' || !ix.data) return 0n;
  let dataBytes;
  try { dataBytes = decodeBase58(ix.data); } catch { return 0n; }
  const resolved = ix.accounts.map((a) => resolveAccountRef(a, keys));
  if (resolved.some((a) => a === null)) return 0n;
  if (dataBytes.length === 9 && dataBytes[0] === 3 && resolved.length >= 4) {
    if (!validDestKeys.has(resolved[1]) || !resolved.slice(3).includes(refKey)) return 0n;
    const amt = readU64Le(dataBytes, 1);
    return amt > 0n ? amt : 0n;
  }
  if (dataBytes.length === 10 && dataBytes[0] === 12 && resolved.length >= 5) {
    if (resolved[1] !== SOL_USDC || !validDestKeys.has(resolved[2]) || !resolved.slice(4).includes(refKey)) return 0n;
    const amt = readU64Le(dataBytes, 1);
    return amt > 0n ? amt : 0n;
  }
  return 0n;
}

function sumMatchedReferenceTransferAmounts(tx, keys, refKey, validDestKeys) {
  if (validDestKeys.size === 0 || !keys.includes(refKey)) return 0n;
  const rawKeys = tx.transaction?.message?.accountKeys || [];
  const numSigners = tx.transaction?.message?.header?.numRequiredSignatures;
  if (typeof numSigners === 'number' && Number.isInteger(numSigners) && numSigners > 0) {
    for (let i = 0; i < Math.min(numSigners, rawKeys.length); i++) {
      if (keys[i] === refKey) return 0n;
    }
  }
  for (const entry of rawKeys) {
    if (entry && typeof entry === 'object' && entry.pubkey === refKey && entry.signer === true) {
      return 0n;
    }
  }
  const topIx = tx.transaction?.message?.instructions;
  const inner = (tx.meta?.innerInstructions || []).flatMap((g) => g?.instructions || []);
  const allIx = [...(Array.isArray(topIx) ? topIx : []), ...inner];
  if (allIx.length === 0) return 0n;
  let total = 0n;
  for (const ix of allIx) {
    total += decodeMatchedSplAmount(ix, keys, refKey, validDestKeys);
  }
  return total;
}

async function verifySignedWebhook(secret, tsHeader, rawPayload, sigHeader) {
  const cleanTs = String(tsHeader || '').trim();
  if (!/^\d{10}$/.test(cleanTs)) {
    throw new Error('Unauthorized: missing or invalid x-webhook-timestamp (Unix seconds required)');
  }
  const nowSec = Math.floor(Date.now() / 1000);
  if (Math.abs(nowSec - Number(cleanTs)) > MAX_WEBHOOK_AGE_SECONDS) {
    throw new Error('Unauthorized: webhook timestamp outside allowed replay window');
  }
  const cleanSig = String(sigHeader || '').trim().replace(/^sha256=/i, '').toLowerCase();
  if (!/^[0-9a-f]{64}$/.test(cleanSig)) {
    throw new Error('Unauthorized: missing or malformed webhook HMAC signature');
  }
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const mac = new Uint8Array(await crypto.subtle.sign('HMAC', key, enc.encode(`${cleanTs}.${rawPayload}`)));
  let diff = 0;
  for (let i = 0; i < 32; i++) {
    const byte = Number.parseInt(cleanSig.slice(i * 2, i * 2 + 2), 16);
    diff |= mac[i] ^ byte;
  }
  if (diff !== 0) {
    throw new Error('Unauthorized: invalid webhook HMAC signature');
  }
}

async function fetchFinalizedTx(signature) {
  const res = await fetch(SOLANA_RPC_URL, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({
      jsonrpc: '2.0',
      id: 1,
      method: 'getTransaction',
      params: [signature, { encoding: 'json', commitment: 'finalized', maxSupportedTransactionVersion: 0 }]
    }),
    signal: AbortSignal.timeout(10000)
  });
  if (!res.ok) throw new Error(`Solana RPC HTTP ${res.status}`);
  const body = await res.json();
  if (body.error) throw new Error(body.error.message || 'Solana RPC error');
  return body.result;
}

const staticData = typeof $getWorkflowStaticData === 'function' ? $getWorkflowStaticData('global') : null;
if (staticData && !Array.isArray(staticData.seenReplayKeys)) {
  staticData.seenReplayKeys = [];
}

const inputItems = typeof $input !== 'undefined' ? $input.all() : items;
const verified = [];

for (const item of inputItems) {
  const json = item.json || {};
  const headers = {};
  for (const [k, v] of Object.entries(json.headers || {})) {
    headers[String(k).toLowerCase()] = String(v ?? '');
  }
  const rawPayload = extractRawPayload(item);
  if (!rawPayload) {
    throw new Error('Unauthorized: missing webhook payload body');
  }
  await verifySignedWebhook(
    SECRET,
    headers['x-webhook-timestamp'],
    rawPayload,
    headers['x-webhook-signature'] || headers['x-signature-256']
  );

  const payload = JSON.parse(rawPayload);
  const signature = String(payload?.signature || '').trim();
  if (!SIG_RE.test(signature)) continue;

  const expectedRef = ALLOW_SIGNED_PAYLOAD_REF
    ? String(payload?.expectedReferenceKey || ENV_EXPECTED_REF).trim()
    : ENV_EXPECTED_REF;
  if (!PUBKEY_RE.test(expectedRef) || expectedRef === VAULT || expectedRef === SOL_USDC) continue;

  const replayKey = await sha256Hex(`solana:${signature}`);
  if (staticData && staticData.seenReplayKeys.includes(replayKey)) continue;

  const tx = await fetchFinalizedTx(signature);
  if (!tx || !tx.meta || tx.meta.err !== null) continue;

  const keys = [];
  pushKeys(keys, tx.transaction?.message?.accountKeys);
  pushKeys(keys, tx.meta?.loadedAddresses?.writable);
  pushKeys(keys, tx.meta?.loadedAddresses?.readonly);
  const validDestKeys = new Set();

  const preMap = new Map();
  for (const b of tx.meta.preTokenBalances || []) {
    if (b.mint === SOL_USDC && b.owner === VAULT && Number.isInteger(b.accountIndex)) {
      if (preMap.has(b.accountIndex)) throw new Error('Duplicate preTokenBalances accountIndex');
      preMap.set(b.accountIndex, parseAtomic(b.uiTokenAmount?.amount, 'preTokenBalance'));
      if (keys[b.accountIndex]) validDestKeys.add(keys[b.accountIndex]);
    }
  }
  const postMap = new Map();
  for (const b of tx.meta.postTokenBalances || []) {
    if (b.mint === SOL_USDC && b.owner === VAULT && Number.isInteger(b.accountIndex)) {
      if (postMap.has(b.accountIndex)) throw new Error('Duplicate postTokenBalances accountIndex');
      postMap.set(b.accountIndex, parseAtomic(b.uiTokenAmount?.amount, 'postTokenBalance'));
      if (keys[b.accountIndex]) validDestKeys.add(keys[b.accountIndex]);
    }
  }

  const matchedIxTotal = sumMatchedReferenceTransferAmounts(tx, keys, expectedRef, validDestKeys);
  if (matchedIxTotal < EXPECTED_AMOUNT_ATOMIC) continue;

  let preTotal = 0n;
  for (const v of preMap.values()) preTotal += v;
  let postTotal = 0n;
  for (const v of postMap.values()) postTotal += v;
  const netDelta = postTotal - preTotal;

  if (netDelta >= EXPECTED_AMOUNT_ATOMIC) {
    if (staticData) {
      staticData.seenReplayKeys.push(replayKey);
      if (staticData.seenReplayKeys.length > 1000) {
        staticData.seenReplayKeys.splice(0, staticData.seenReplayKeys.length - 1000);
      }
    }
    verified.push({
      json: {
        event: 'solana_usdc_settled',
        replayKey,
        signature,
        recipientOwner: VAULT,
        referenceKey: expectedRef,
        amountAtomic: netDelta.toString(),
        slot: tx.slot
      }
    });
  }
}

return verified;
